module BipartiteBattle(\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] N,\n    input [7:0] a_i [0:7],\n    input [7:0] b_i [0:7],\n    output reg [31:0] result,\n    output reg done\n);\n    parameter [31:0] MOD = 32'd1000000007;\n    \n    // State definitions\n    localparam [2:0] IDLE         = 3'd0;\n    localparam [2:0] SUM_AND_COUNT = 3'd1;\n    localparam [2:0] CHECK_CNT     = 3'd2;\n    localparam [2:0] COMPUTE_POWER = 3'd3;\n    localparam [2:0] FINISH        = 3'd4;\n    \n    reg [2:0] state;\n    reg [31:0] total_edges;\n    reg [31:0] cnt;\n    reg [2:0] idx;\n    reg [31:0] power;\n    reg [31:0] exponent;\n    reg [7:0] cycle_count;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            total_edges <= 32'd0;\n            cnt <= 32'd0;\n            idx <= 3'd0;\n            power <= 32'd0;\n            exponent <= 32'd0;\n            result <= 32'd0;\n            done <= 1'b0;\n            cycle_count <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= SUM_AND_COUNT;\n                        total_edges <= 32'd0;\n                        cnt <= 32'd0;\n                        idx <= 3'd0;\n                    end\n                end\n                \n                SUM_AND_COUNT: begin\n                    if (idx < N) begin\n                        total_edges <= total_edges + (a_i[idx] * b_i[idx]);\n                        if (a_i[idx][0] && b_i[idx][0]) begin\n                            cnt <= cnt + 32'd1;\n                        end\n                        idx <= idx + 3'd1;\n                    end else begin\n                        state <= CHECK_CNT;\n                    end\n                end\n                \n                CHECK_CNT: begin\n                    if (cnt[0] == 1'b0) begin\n                        result <= 32'd0;\n                        state <= FINISH;\n                    end else begin\n                        exponent <= total_edges - 32'd1;\n                        power <= 32'd1;\n                        cycle_count <= 8'd0;\n                        state <= COMPUTE_POWER;\n                    end\n                end\n                \n                COMPUTE_POWER: begin\n                    if (exponent > 32'd0 && cycle_count < 8'd100) begin\n                        power <= (power * 32'd2) % MOD;\n                        exponent <= exponent - 32'd1;\n                        cycle_count <= cycle_count + 8'd1;\n                    end else begin\n                        result <= power;\n                        state <= FINISH;\n                    end\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule